352→async function getUsers(prisma, signerFields, companyId) {
353→    const users = [];
354→    for (const signer of signerFields) {
355→        const user = await findOrCreateUser(prisma, signer, companyId);
356→        users.push(user);
357→    }
358→    return users;
359→}
