361→async function findOrCreateUser(prisma, signer, companyId) {
362→
363→    let user;
364→
365→    if (signer.user_id) {
366→        user = await prisma.users.findFirst({
367→            where: {
368→                id: parseInt(signer.user_id)
369→            },
370→            select: { id: true, email: true, firstname: true, lastname: true, id_number: true, doc_type: true }
371→        });
372→    }
373→
374→    if (!user) {
375→        user = await prisma.users.findFirst({
376→            where: {
377→                OR: [
378→                    { email: signer.correo },
379→                   // { id_number: String(signer.documento), id_type: parseInt(signer.tipo_documento) }
380→                ]
381→            },
382→            select: { id: true, email: true, firstname: true, lastname: true, id_number: true, doc_type: true }
383→        });
384→    }
385→
386→    if (!user) {
387→        user = await prisma.users.create({
388→            data: {
389→                firstname: signer.nombres,
390→                lastname: signer.apellidos,
391→                email: signer.correo,
392→                password: genApiKey.generateApiKey({ method: "base32", dashes: false }),
393→                type: "3",
394→                role_id: "3",
395→                signer: "1",
396→                active: "1",
397→                accept_terms_and_conditions: "false",
398→                id_number: String(signer.documento),
399→                id_type: parseInt(signer.tipo_documento),
400→                company_id: companyId,
401→                two_factor_login: "false",
402→                created_at: new Date()
403→            }
404→        });
405→    }
406→
407→    return user;
