113→async function modifyPdfWithFields(pdfBuffer, fields, signer_fields) {
114→    try {
115→        const pdfDoc = await PDFDocument.load(pdfBuffer);
116→        const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
117→        const timesRomanFont = await pdfDoc.embedFont(StandardFonts.TimesRoman);
118→
119→        const MIN_FONT_SIZE = 9;
120→        const MAX_FONT_SIZE = 11;
121→        const LINE_SPACING = 3;
122→
123→        const marginTopInside = 45;
124→        const marginBottomInside = 10;
125→        const EXTRA_TEXT_SHIFT = 5;
126→
127→        if (!Array.isArray(fields) || fields.length === 0) {
128→            console.warn("'fields' está vacío o no es un array.");
129→            return pdfBuffer;
130→        }
131→
132→        for (const field of fields) {
133→            try {
134→
135→                const { pageNumber, top, left, width, height, name, includeFullName, includeDocumentInfo} = field;
136→
137→                if (!pageNumber || !top || !left || !width || !height || !name) {
138→                    console.warn("Field con datos incompletos:", field);
139→                    continue;
140→                }
141→
142→                const page = pdfDoc.getPage(pageNumber - 1);
143→                if (!page) {
144→                    console.warn(`Página ${pageNumber} no encontrada en el PDF.`);
145→                    continue;
146→                }
147→
148→                const pageHeight = page.getHeight();
149→                const pdfX = left;
150→                const pdfY = pageHeight - top - height;
151→                const pdfWidth = width - 6;
152→                const pdfHeight = height + 2;
153→
154→                const matchingSigners = signer_fields.filter(f => f.name === name);
155→               
156→             /*    page.drawRectangle({
157→                    x: pdfX,
158→                    y: pdfY,
159→                    width,
160→                    height,
161→                    borderColor: rgb(1, 0, 0), 
162→                    borderWidth: 1,
163→                }); */
164→
165→                let signerLines = 0;
166→                if (includeFullName) signerLines++;
167→                if (includeDocumentInfo) signerLines++;
168→
169→                let lineCount = (signerLines * matchingSigners.length);
170→                let fontSize = MAX_FONT_SIZE;
171→
172→                while (fontSize > MIN_FONT_SIZE) {
173→                    const neededHeight = lineCount * (fontSize + LINE_SPACING);
174→                    const textWidth = helveticaFont.widthOfTextAtSize(name, fontSize);
175→
176→                    if (neededHeight <= pdfHeight && textWidth <= pdfWidth - 10) {
