206→                            y: docY,
207→                            font: timesRomanFont,
208→                            size: fontSize,
209→                        });
210→
211→                        docY += fontSize + LINE_SPACING;
212→
213→                        const centeredFullNameX = pdfX + EXTRA_TEXT_SHIFT;
214→                        page.drawText(fullName, {
