344→async function createDocumentPackageSigner(prisma, req, companyId, userId, recipients, send_reminder, reminder_days_interval, name) {
345→    const fingerprint = await generateFingerPrint();
346→
347→    let expiresDateStr = req.body.expires_in_days;
348→
349→    if (expiresDateStr && !expiresDateStr.match(/\d{2}:\d{2}/)) {
350→        expiresDateStr = `${expiresDateStr} 00:00`;
351→    }
352→
353→    const expires_date = new Date(expiresDateStr);
354→    const formatted_expires_date = expires_date.toISOString();
355→
356→    const current_date = new Date();
357→    const formatted_current_date = current_date.toISOString();
358→
359→    const request = await prisma.document_packages_signers.create({
360→        data: {
361→            user_id: parseInt(userId),
362→            company_id: parseInt(companyId),
363→            status: "send",
364→            token: "",
365→            is_pdf: 1,
366→            sent_sign_request_at: formatted_current_date,
367→            scheduled_send_at: req.body.send_date ? new Date(req.body.send_date).toISOString() : null,
368→            fingerprint: fingerprint.replace(":", ""),
369→            ip_address: req.ip,
370→            user_id_creator: parseInt(req.body.user_id_creator),
371→            send_reminder: send_reminder == 1 ? true : false,
372→            reminder_days_interval: reminder_days_interval ? parseInt(reminder_days_interval): null,
373→            active: "1",
374→            package_name: name ? name : "Sin nombre",
375→            expires_in_days: formatted_expires_date,
376→            created_at: new Date(),
377→            updated_at: new Date()
378→        }
379→    });
380→
381→    if (req.body.additionalOptions) {
382→        const additionalOptions = req.body.additionalOptions;
383→
384→        if (additionalOptions && additionalOptions.length > 0) {
385→            for (const option of additionalOptions) {
386→
387→                if (parseInt(option.enabled) === 1) {
388→                    await prisma.signature_features.create({
389→                        data: {
390→                            document_package_signer_id: request.id,
391→                            feature_id: parseInt(option.id),
392→                            created_at: new Date(),
393→                            updated_at: new Date()
394→                        }
395→                    });
396→                }
397→            }
398→        }
399→    }
400→
401→    if (recipients.length > 0) {
402→        const validRecipients = recipients.filter(recipient => recipient && recipient.trim() !== '');
403→
404→        if (validRecipients.length > 0) {
405→
406→            const insertPromises = recipients.map((recipient) => {
407→                return prisma.request_recipients.create({
408→                    data: {
