481→async function sendSignRequests(res, documentPackageSigner, users, company, signerFields, packageName, prisma) {
482→    const requests = [];
483→
484→    for (const user of users) {
485→        const token = service.createCustomToken({
486→            id: user.id,
487→            document_package_signer_id: documentPackageSigner.id,
488→        });
489→
490→        const fingerprint = await generateFingerPrint();
491→
492→        const signerField = signerFields.find(field => field.correo.toLowerCase() === user.email.toLowerCase());
493→        
494→        if (!signerField) {
495→            console.warn(`Advertencia: No se encontró signerField para el usuario con correo: ${user.email}`);
496→            continue;  
497→        }
498→
499→        const firstFieldName = signerField
500→            ? signerField.name 
501→            : null;
502→
503→
504→        const orderMatch = firstFieldName.match(/\[(\d+)\]/);
505→        const order = orderMatch ? parseInt(orderMatch[1], 10) : users.indexOf(user) + 1;
506→
507→        await prisma.document_signers.create({
508→            data: {
509→                document_package_signer_id: documentPackageSigner.id,
510→                user_id: parseInt(user.id),
511→                order: order, 
512→                status: "send",
513→                token: token,
514→                sent_sign_request_at: new Date(),
515→                fingerprint: fingerprint.replace(":", ""),
516→                expires_in_days: documentPackageSigner.expires_in_days,
517→                created_at: new Date(),
518→                updated_at: new Date()
519→            },
520→        });
521→
522→        const url = `${process.env.ENV_URL}${token}`;
523→        requests.push({
524→            id: user.id,
525→            document_package_signer_id: documentPackageSigner.id,
526→            email: user.email,
527→            company: company,
528→            firstname: user.firstname,
529→            lastname: user.lastname,
530→            passwordGenerated: genApiKey.generateApiKey({ method: "base32", dashes: false }),
531→            date: documentPackageSigner.expires_in_days.toLocaleDateString('es-ES'),
532→            time: documentPackageSigner.expires_in_days.toLocaleTimeString(),
533→            _url: url,
534→            company_email: company.email,
535→            sendRequest: true
536→        });
537→    }
538→
539→    const scheduledAt = documentPackageSigner.scheduled_send_at;
540→    const now = new Date();
541→
542→    const isImmediate = !scheduledAt || new Date(scheduledAt) <= now;
543→
544→    if (isImmediate) {
545→        await Promise.all(requests.map(async (user) => {
546→            if (user.sendRequest) {
547→                await service.sendSolicitudFirma(
548→                    user.email,
549→                    user.company.avatar,
550→                    `${user.firstname} ${user.lastname}`,
551→                    user.company.fiscal_name,
552→                    user.company.fiscal_name,
553→                    user.passwordGenerated,
554→                    user.date,
555→                    user.time,
556→                    user._url,
557→                    user.company_email,
558→                    packageName,
559→                    user.company.advanced_settings[0].email_message,
560→                    user.id,
561→                    user.document_package_signer_id,
562→                    user.company.id
563→                );
564→                user.sendRequest = false;
565→            }
566→        }));
567→
568→    } else {
569→       await signRequestQueue.add(
570→            { requests, packageName, isPdf: true },
571→            {
572→                delay: new Date(scheduledAt).getTime() - now.getTime(),
573→                attempts: 3,
574→            }
575→        );
576→    }
577→
578→    res.status(200).send({
579→        status: true,
580→        data: {
581→            request_id: documentPackageSigner.id,
582→            user_id: documentPackageSigner.user_id,
583→            company_id: documentPackageSigner.company_id
584→        },
585→        message: isImmediate
586→            ? "Solicitud enviada exitosamente"
